$('locate').onclick=()=>{
 if(!map)return;
 if(!navigator.geolocation){toast('Geolocation is unavailable. Search an address or enter coordinates.');return}
 const button=$('locate');
 function finish(){button.disabled=false;button.setAttribute('aria-busy','false');button.setAttribute('aria-label',t('Locate me'));button.title=t('Locate me')}
 button.disabled=true;button.setAttribute('aria-busy','true');button.setAttribute('aria-label',t('Finding your location'));button.title=t('Finding your location…');
 toast('Finding your location… Allow location access if your browser asks.');
 try{navigator.geolocation.getCurrentPosition(position=>{
  finish();const {latitude:lat,longitude:lon,accuracy}=position.coords;
  locationAccuracy=U.accuracyPolygon(lat,lon,accuracy);
  if(ready)map.getSource('accuracy').setData({type:'FeatureCollection',features:[locationAccuracy]});
  select({id:'my-location',name:'Your location',lat,lon,accuracy},true);
  toast('Location found. Accuracy: ±'+Math.round(accuracy)+' m.');
 },error=>{
  finish();toast(error.code===1?'Location permission denied. Search an address or enter coordinates instead.':error.code===3?'Location request timed out. Try again or enter an address.':'Location could not be determined. Try address search.');
 },{enableHighAccuracy:false,timeout:8000,maximumAge:60000})}
 catch{finish();toast('Location is unavailable in this browser. Search an address or enter coordinates instead.')}
};
const searches=new Map();$('search-form').onsubmit=async e=>{e.preventDefault();if(!map)return;const q=$('search').value.trim(),results=$('search-results');let coordinates;try{coordinates=U.parseCoordinates(q)}catch(error){toast(error.message);return}if(coordinates){select({id:'coords:'+q,name:'Pinned coordinates',...coordinates},true);results.hidden=true;return}if(q.length<3){toast('Enter a place, address, or latitude and longitude.');return}if(Date.now()<searchAfter){toast('Please wait a moment before searching again.');return}searchAfter=Date.now()+1500;searchController?.abort();searchController=new AbortController();const token=++searchSeq;results.hidden=false;results.replaceChildren(node('p','Searching addresses and places…'));try{let data=searches.get(q.toLowerCase());if(!data){data=await json('https://photon.komoot.io/api/?'+new URLSearchParams({q,limit:6}),searchController.signal);searches.set(q.toLowerCase(),data)}if(token!==searchSeq)return;results.replaceChildren();const features=(data.features||[]).filter(f=>f.geometry?.type==='Point'&&f.geometry.coordinates.slice(0,2).every(Number.isFinite));if(!features.length)results.append(node('p','No matching places. Try a city, postcode or a more complete address.'));for(const f of features){const p=f.properties||{},label=p.name||[p.housenumber,p.street].filter(Boolean).join(' ')||p.city||q,address=[p.housenumber,p.street,p.city,p.state,p.country].filter(Boolean).join(', '),button=node('button');button.type='button';button.append(node('span',label),node('small',address));button.onclick=()=>{results.hidden=true;select({id:'search:'+(p.osm_id||q),name:label,address,lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0]},true)};results.append(button)}}catch(error){if(token===searchSeq)results.replaceChildren(node('p','Address search unavailable. Try coordinates or retry later.'))}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDetail();$('search-results').hidden=true;$('sources').hidden=true}});document.addEventListener('click',e=>{if(!e.target.closest('#search-form'))$('search-results').hidden=true});setInterval(()=>{if(document.hidden||previewPaused)return;renderCities();renderSaved();if(selected&&!$('detail').hidden){showPlace(selected,false);weather(selected)}schedule()},60000);renderStatic();document.documentElement.lang=language==='zh'?'zh-Hans':'en';$('map-language').value=language;renderPalette();if(embedded){$('application').append($('locate'));$('locate').classList.add('embed-locate');$('layers').hidden=true;layersOpen=false;window.addEventListener('message',event=>{if(event.source!==parent||event.data?.type!=='nori-preview-visibility')return;previewPaused=!event.data.visible;if(previewPaused){clearTimeout(viewTimer);providerController.abort()}else if(ready)schedule()})}init();
